// План specs/support.md, 1.4 (кейс SUP-04). Admin, иврит. Только чтение: не отвечать, не нажимать «סגור». @prod-safe
import { test, expect, Page } from '@playwright/test';
import { setLanguage } from '../admin-plans/plans-helpers';
import {
  ADMIN_STATE, CHAT_TAB_HE, DETAIL_HEADER_HE, INBOX_HEADER_HE, expectAllStamps, openInboxChat, openTicketDetail, stamps,
} from './support-helpers';

test.use({ storageState: ADMIN_STATE, timezoneId: 'Asia/Jerusalem' });

/** Каждая метка — дата перед временем, направление ltr (в RTL не переворачивается). */
async function expectLtrStamps(page: Page) {
  await expectAllStamps(page);
  const dirs = await stamps(page).evaluateAll((els) => els.map((e) => getComputedStyle(e).direction));
  expect(dirs.every((d) => d === 'ltr'), `direction: ${dirs.join(',')}`).toBe(true);
}

test.describe('Поддержка — дата и время сообщений (#3db49a08)', () => {
  test('Hebrew UI keeps date before time and LTR direction on ticket detail and Support Console #3db49a08 @desktop @prod-safe', async ({ page }) => {
    await setLanguage(page, 'he');

    // Шаг 1: экран обращения — шапка «צ׳אט · DD/MM/YY HH:mm»
    await openTicketDetail(page, DETAIL_HEADER_HE);
    await expectLtrStamps(page);

    // Шаг 2: ממשק תמיכה → צ׳אט → QA-обращение
    await openInboxChat(page, CHAT_TAB_HE, INBOX_HEADER_HE);
    await expectLtrStamps(page);
  });
});
